SELECT (CASE WHEN ("Eixo_1"."no_dependencia_admin" = 'Privada') THEN "Eixo_1"."mantenedora" ELSE "Eixo_1"."instituicao" END) AS "Calculation_838513978982854656",   MIN("Eixo_1"."data_de_inicio") AS "TEMP_attr_data_de_inicio_ok__3982078387__0_",   MAX("Eixo_1"."data_de_inicio") AS "TEMP_attr_data_de_inicio_ok__86782374__0_",   MIN("Eixo_1"."data_de_previsaode_termino") AS "TEMP_attr_data_de_previsaode_termino_ok__4171852708__0_",   MAX("Eixo_1"."data_de_previsaode_termino") AS "TEMP_attr_data_de_previsaode_termino_ok__570103144__0_",   "Eixo_1"."cpf_aluno" AS "cpf_aluno",   "Eixo_1"."nome_aluno" AS "nome_aluno",   "Eixo_1"."nome_da_sit_matricula__situacao_detalhada_" AS "nome_da_sit_matricula__situacao_detalhada_",   "Eixo_1"."nome_curso_catalogo_guia" AS "nome_curso_catalogo_guia",   SUM(CAST("Eixo_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   SUM(CAST("Eixo_1"."total_freq_aluno" AS BIGINT)) AS "sum_total_freq_aluno_ok" FROM "Eixo_1" WHERE (("Eixo_1"."nome_aluno" = 'AMANDA APARECIDA DE JESUS RODRIGUES') AND (NOT (("Eixo_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR ("Eixo_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND ("Eixo_1"."nome_curso_catalogo_guia" = 'TÉCNICO EM ENFERMAGEM') AND (NOT ("Eixo_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "Calculation_838513978982854656",   "cpf_aluno",   "nome_aluno",   "nome_da_sit_matricula__situacao_detalhada_",   "nome_curso_catalogo_guia";
